internal object DuaKoDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("내 행위의 악에서 피난처", "오 알라, 나는 내가 행한 악과 내가 행하지 않은 악으로부터 당신께 피난처를 구합니다.", "아이샤 (RA)에 따르면 예언자 ﷺ의 듀아.", "수행된 작업과 수행되지 않은 작업의 결과로부터 보호합니다."),
        "dua_jahdil_bala" to DuaText("혹독한 시련으로부터의 피난처", "오 알라, 나는 심한 시련과 비참함, 악한 법령과 적들의 찬사로부터 당신께 피난처를 구합니다.", "혹독한 시련과 적들의 영광을 피하십시오.", "선지자 ﷺ은 이 네 가지로부터 피난처를 찾았습니다."),
        "dua_fitnat_ghina_faqr" to DuaText("부와 빈곤의 시련을 피하세요", "오 알라, 나는 게으름과 노년, 죄와 빚, 무덤의 시련과 형벌, 불의 시련과 형벌, 부의 시련의 악, 가난의 시련으로부터 당신께 피난처를 구합니다.", "무덤, 지옥, 부와 빈곤의 시련으로부터 피난처(두아의 일부).", "선지자 ﷺ의 포괄적인 피난처 이중."),
        "dua_kufr_faqr" to DuaText("불신과 가난으로부터의 피난처", "오 알라, 나는 불신과 가난으로부터 당신께 피난처를 구하며, 무덤의 형벌로부터 당신께 피난처를 구합니다. 당신 외에는 신이 없습니다.", "아침저녁으로 세 번.", "아부 바크라 (RA)은 예언자 ﷺ이 이렇게 말하는 것을 들었습니다."),
        "dua_sharri_sami" to DuaText("내 감각의 악으로부터 피난처", "오 알라, 나는 내 청각의 악함, 내 눈의 악함, 내 혀의 악함, 내 마음의 악함, 내 욕망의 악함으로부터 당신께 피난처를 구합니다.", "Shakal ibn Humayd (RA)에게 가르쳤습니다.", "죄로부터 팔다리와 자신을 보호하기 위한 이중."),
        "dua_hadm_gharaq" to DuaText("돌연사 및 사고로부터의 피난", "오 알라, 나는 (건물에 의해) 부서지고, 높은 곳에서 떨어지고, 익사하고, 불타고, 늙어가는 것으로부터 당신께 피난처를 구합니다. 죽음의 순간에 나를 잘못된 길로 인도한 샤이탄으로부터, 당신의 길에서 도망치다가 죽는 것으로부터, 그리고 (독이 있는) 쏘임으로 죽는 것으로부터.", "사고와 나쁜 죽음으로부터 피난처.", "선지자 ﷺ의 피난처 이중."),
        "dua_ju_khiyanah" to DuaText("굶주림과 배신으로부터의 피난처", "오 알라, 나는 배고픔으로부터 당신께 피난처를 구합니다. 왜냐하면 그것은 악한 동반자이기 때문이며, 나는 당신에게 배반으로부터 피난처를 구합니다. 왜냐하면 그것은 사악한 친구이기 때문입니다.", "배고픔과 배신으로부터 피난처를 찾으세요.", "선지자 ﷺ의 피난처 이중."),
        "dua_huda_tuqa" to DuaText("인도, 경건, 순결과 충분함", "오 알라, 나는 당신에게 인도와 경건함, 순결과 자급 자족을 구합니다.", "선지자 ﷺ의 짧고 포괄적인 이중문입니다.", "종교와 이 세상의 네 가지 기본 축복."),
        "dua_aslih_li_dini" to DuaText("나의 종교와 세상과 내세를 바로잡아라", "오 알라시여, 나의 모든 일의 보호가 되는 나의 종교를 바로잡아 주소서. 나의 생계가 되는 세상의 삶을 바로잡아 주소서. 그리고 내가 돌아갈 내세를 바로잡아 주십시오. 모든 선한 일에 생명을 더하게 하시고, 죽음이 모든 악에서 나를 구원하게 하소서.", "종교를 개혁하는 것, 현세와 내세 - 이 세 가지 모두.", "예언자 ﷺ의 포괄적인 이중입니다."),
        "dua_musarrifal_qulub" to DuaText("우리 마음을 당신의 순종으로 바꾸십시오", "오 알라, 마음을 돌리시는 분이시여, 우리 마음을 당신께 순종하게 하소서.", "순종하는 마음을 굳건히 유지하는 듀아.", "모든 사람의 마음은 가장 자비로우신 분의 두 손가락 사이에 있습니다."),
        "dua_jannah_nar" to DuaText("불을 피해 피난처인 잔나를 구해오다", "오 알라, 나는 당신에게 천국을 구하며 불로부터 당신 안에서 피난처를 구합니다.", "tashahhud 이후 또는 언제든지.", "예언자 ﷺ은 이렇게 말했습니다: 우리 두 사람도 이 문제를 중심으로 돌아갑니다."),
        "dua_khayri_kullih" to DuaText("지금과 나중 모두 좋습니다", "오 알라, 나는 당신에게 즉각적인 것과 지연된 것, 내가 아는 것과 모르는 것 등 모든 좋은 것을 간구하며, 즉각적이고 지연된 것, 내가 아는 것과 모르는 것 등 모든 악으로부터 당신께 피난처를 구합니다. 오 알라, 나는 당신에게 낙원을 간청하며, 어떤 말과 행동이 나를 천국에 가까이 가게 하는지 구하며, 불로부터, 그리고 어떤 말과 행동이 나를 천국에 가까이 데려가는지로부터 당신께 피난처를 구합니다.", "예언자 ﷺ은 이 포괄적인 듀아를 아이샤 (RA)(듀아의 일부)에게 가르쳤습니다.", "모든 좋은 것을 모으는 듀아."),
        "dua_ihdini_saddidni" to DuaText("나를 인도하고 나를 바로 세우십시오", "오 알라시여, 나를 인도하시고 올바른 길로 갈 수 있도록 지켜주소서.", "예언자 ﷺ이 알리 (RA)에게 가르쳤습니다.", "안내를 길을 따라 안내하는 것으로 생각하고, 사다드를 화살의 직선으로 생각하십시오."),
        "dua_hubbaka" to DuaText("알라의 사랑을 구하다", "오 알라, 나는 당신에게 당신의 사랑과 당신을 사랑하는 사람들의 사랑, 그리고 나를 당신의 사랑으로 이끄는 행동을 간구합니다. 오 알라, 당신의 사랑을 나 자신, 내 가족, 차가운 물보다 더 소중하게 만드십시오.", "예언자 ﷺ과 관련된 Dawud (AS)의 듀아.", "알라의 사랑은 가장 큰 부입니다."),
        "dua_filal_khayrat" to DuaText("선을 행하고 악을 떠나", "오 알라, 제가 선한 일을 할 수 있게 하시고, 악한 일을 버리며, 가난한 이들을 사랑할 수 있게 하시고, 저를 용서하시고 자비를 베푸소서. 그리고 당신께서 백성을 재판하려고 하실 때, 재판을 받지 않고 나를 데려가소서. 당신의 사랑과 당신을 사랑하는 이들의 사랑, 그리고 저를 당신의 사랑에 가까이 데려갈 수 있는 행위에 대한 사랑을 구합니다.", "알라는 꿈에서 이 두아를 선지자 ﷺ에게 가르쳤습니다.", "선지자 ﷺ은 이렇게 말했습니다: 그것은 사실이므로 배우고 가르치십시오."),
        "dua_bi_ilmikal_ghayb" to DuaText("인생이 좋을 때 살게 해주세요", "오 알라, 보이지 않는 것에 대한 당신의 지식과 창조물에 대한 당신의 능력으로 당신이 삶이 나에게 더 낫다는 것을 아시는 한 나를 살려주시고, 죽음이 나에게 더 낫다는 것을 아시는 동안 나를 데려가소서. 오 알라, 나는 사적으로나 공개적으로 당신을 두려워하고, 만족할 때와 분노할 때, 그리고 가난과 부에서 절제를 구합니다.", "Ammar ibn Yasir (RA)의 기도문(오프닝 부분).", "선지자 ﷺ은 기도로 이 두아를 만들었습니다."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: 알-만난", "오 알라, 나는 당신에게 간구합니다. 왜냐하면 당신께 모든 찬양이 있기 때문입니다. 은혜를 베푸시는 분, 하늘과 땅의 창시자이신 당신 외에는 신이 없나이다. 오 위엄과 명예를 가지신 분, 오 영원하신 분, 오 유지하시는 분!", "예언자 ﷺ은 이 사람이 알라의 가장 위대한 이름과 듀아를 만들었다고 말했습니다.", "이 이름으로 만든 듀아가 응답됩니다."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: 알아하드 아스사마드(Al-Ahad As-Samad)", "오 알라, 나는 당신에게 간구합니다. 왜냐하면 나는 당신이 알라임을 증언하기 때문입니다. 자급자족하시는 분, 당신 외에는 신이 없고, 낳지도 태어나지도 않으시며, 그분과 비교할 수 있는 신이 없습니다.", "선지자 ﷺ은 이 사람이 알라에게 그의 가장 위대한 이름을 물었다고 말했습니다.", "요청하면 그분은 주십니다. 그것이 부르면 그분은 응답하십니다."),
        "dua_thabbitni_hadiyan" to DuaText("나를 굳건하게 하시고 인도하시고 인도하게 하소서", "오 알라시여, 나를 확고하게 하시고 인도하고 인도하는 자로 만들어 주소서.", "예언자 ﷺ은 Jarir (RA)을 위해 이 두아를 만들었습니다(스스로 'thabbitni'라고 말하세요).", "Jarir (RA)의 원래 이중어는 'thabbit-hu'라는 단어를 사용합니다."),
        "dua_rabbighfir_tub_alayya" to DuaText("나를 용서하고 나의 회개를 받아들이십시오", "주님, 저를 용서하시고 저의 회개를 받아주소서. 참으로 당신은 회개를 받아들이시는 자비로우신 분이십니다.", "한 번 앉은 자리에서 백 번 — 선지자의 실천 ﷺ.", "동료들은 선지자 ﷺ이 앉은 자리에서 이 말을 백 번이나 한 것으로 기록했습니다."),
        "dua_rafiq_ala" to DuaText("죽어가는 사람의 두아", "오 알라, 저를 용서하시고, 저에게 자비를 베풀어 주시고, 가장 높은 동반자와 함께 저와 함께 하소서.", "예언자 ﷺ의 마지막 두아 – 아픈 사람이 스스로 말하는 것입니다.", "예언자 ﷺ은 세상을 떠날 때 이 두아를 만들었습니다."),
        "dua_la_bas_tahur" to DuaText("병자를 위로함: 정화", "해를 끼치 지 않습니다. 알라께서 원하신다면 그것은 (죄로부터) 정화되는 것입니다.", "방문할 때 아픈 사람들을 위로하기 위해.", "선지자 ﷺ은 병자를 방문할 때 이렇게 말했습니다."),
        "dua_talqeen" to DuaText("죽어가는 사람들을 위한 탈퀸", "알라 외에는 누구도 숭배받을 권리가 없습니다.", "죽어가는 사람 근처에서 칼리마를 낭송하십시오(그에게 말하도록 강요하지 마십시오).", "누구든지 마지막 말이 'La ilaha illallah'인 사람은 천국에 들어갈 것입니다(Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("죽음을 바라는 대신", "오 알라, 삶이 나에게 더 나은 한 나를 살려주시고, 죽음이 나에게 더 나을 때 나를 데려가소서.", "고난 속에 죽기를 바라는 대신.", "예언자 ﷺ은 죽음을 바라는 것을 금지하고 대신 이것을 가르쳤습니다."),
        "dua_for_one_i_cursed" to DuaText("말로 상처받은 누군가를 위해", "오 알라, 내가 모욕한 신자가 부활의 날에 그를 위해 당신에게 가까이 다가갈 수 있는 수단이 되게 하소서.", "당신이 화를 내며 나쁜 말을 한 사람에게.", "예언자 ﷺ의 이중곡."),
        "dua_praising_someone" to DuaText("누군가를 칭찬할 때", "나는 누구누구가 이와 같다고 생각하며 알라는 그의 계산자이며 알라 앞에서 누구의 순결을 보증하지 않습니다.", "누군가를 칭찬할 때, 과장하는 대신.", "선지자 ﷺ은 이러한 찬양 예절을 가르쳤습니다."),
        "dua_being_praised" to DuaText("칭찬받을 때", "오 알라시여, 그들이 말하는 것을 저로 여기지 마시고 그들이 모르는 것을 용서해 주십시오.", "자신이 칭찬받는 것을 들을 때 — 동반자의 실천 (RA).", "칭찬받을 때 오만함을 피하는 방법."),
        "dua_non_muslim_sneezes" to DuaText("무슬림이 아닌 사람이 재채기를 할 때", "알라가 당신을 인도하고 당신의 일을 바로잡기를 바랍니다.", "무슬림이 아닌 사람이 재채기를 하며 '알함둘릴라'라고 말할 때.", "유대인들은 선지자 ﷺ이 '야르하무칼라'라고 말하기를 바라며 그 근처에서 재채기를 했고, 그는 이렇게 말했습니다."),
        "dua_reply_ahl_kitab_salam" to DuaText("책의 사람들의 살람에게 답장하기", "그리고 당신에게.", "책의 사람들이 살람으로 인사할 때.", "선지자의 지시 ﷺ."),
        "dua_fasting_invited" to DuaText("금식하는 동안 초대받았을 때", "나는 금식하고 있습니다.", "금식 중에 초대를 받았을 때나 누군가가 당신과 다투었을 때.", "단식하는 사람이 초대를 수락하면 호스트를 위해 기도해야 합니다."),
        "dua_for_who_gave_drink" to DuaText("나에게 먹이를 준 사람을 위해", "오 알라시여, 나에게 밥을 주신 분에게 먹이를 주시고, 나에게 물을 주신 분에게 물을 주십시오.", "너희에게 먹을 것과 마실 것을 주는 자를 위하여.", "예언자 ﷺ은 알 미크다드 (RA)을 위해 이 듀아를 만들었습니다."),
        "dua_eid_greeting" to DuaText("이드 인사말", "알라께서 우리와 당신에게서 (선한 행위)를 받아들이시기를 바랍니다.", "이드(Eid) 날 서로에게 – 고귀한 동료들의 실천 (RA).", "동행자들은 이드(Eid)에 만났을 때 이렇게 말했습니다."),
        "dua_wedding_night" to DuaText("니카 이후의 신부를 위해", "오 알라, 나는 당신에게 그녀의 선함과 당신이 그녀를 창조한 본성의 선함을 구하며 그녀의 악과 당신이 그녀를 창조한 본성의 악으로부터 당신께 피난처를 구합니다.", "니카 후에는 아내의 이마에 손을 얹습니다.", "선지자의 ﷺ 가르침 — 결혼의 축복."),
        "dua_istisqa_ibadak" to DuaText("하인과 동물에게 물을 주세요", "오 알라, 당신의 종들과 동물들에게 물을 주시고 자비를 베푸시며 당신의 죽은 땅에 생명을 주소서.", "비(istisqa)를 구합니다.", "예언자 ﷺ은 비를 위해 이 듀아를 만들었습니다."),
        "dua_seeing_clouds" to DuaText("어두운 구름을 보다", "오 알라, 나는 그 악으로부터 당신께 피난처를 구합니다.", "하늘에 먹구름이 보이니 비가 오면 'Allahumma sayyiban nafi'a'라고 말하세요.", "구름을 보자 예언자 ﷺ은 하던 일을 그만두고 이 두아를 만들었습니다."),
        "dua_jamarat" to DuaText("자마라트에게 돌을 던지기", "알라는 가장 위대하다.", "조약돌을 던질 때마다.", "예언자 ﷺ은 모든 조약돌에 대해 takbir을 말한 다음 첫 번째와 두 번째 jamrah가 Qiblah를 향한 후 긴 dua를 만들었습니다."),
        "dua_rabbi_ainni" to DuaText("나의 주님, 나를 도와주시고 반대하지 마십시오", "나의 주님, 나를 도우시고 다른 사람들이 나에게 대항하도록 돕지 마십시오. 나에게 승리를 허락하시고 다른 사람들이 나에 대해 승리하도록 허락하지 마십시오. 나를 위한 계획을 세우고 나를 반대할 계획을 세우지 마십시오.", "선지자 ﷺ의 포괄적인 이중(개막 부분).", "종교와 이 세상의 모든 도움을 모으는 듀아."),
        "dua_ati_nafsi_taqwaha" to DuaText("내 영혼에 Taqwa를 부여하세요", "오 알라시여, 내 영혼에 경건함을 주시고 깨끗하게 하소서. 당신은 그것을 정화하는 데 가장 뛰어나시기 때문입니다. 당신은 그것의 수호자이자 주인입니다.", "자아를 개혁하고 정화하기 위해.", "예언자 ﷺ이 이 듀아를 만들곤 했습니다."),
        "dua_iqsim_lana_khashyatik" to DuaText("우리에게 당신에 대한 그런 두려움을 주소서", "오 알라, 우리 사이에 끼어들고 당신에게 불순종할 만큼 당신에 대한 충분한 두려움을, 우리를 당신의 낙원으로 인도할 만큼 충분한 순종을, 그리고 이 세상의 재난을 우리가 쉽게 할 수 있도록 충분한 확신을 주소서. 당신이 우리를 살아 있게 하시고 우리보다 더 오래 지속되게 하시는 한 우리의 청각과 시각과 힘을 누리게 하소서. 우리에게 잘못한 자들에게 복수하고, 우리의 적들에 맞서 우리를 도우시고, 우리의 재난이 우리 종교에 있지 않도록 하시고, 이 세상을 우리의 가장 큰 관심사나 우리 지식의 한계로 삼지 마시고, 우리에게 자비를 베풀지 않는 자들을 우리 위에 두지 마소서.", "모임에서 일어날 때 — 선지자 ﷺ은 이 두아를 만들지 않고는 거의 일어나지 않았습니다.", "종교와 현세와 내세의 이익을 위한 포괄적인 이중입니다."),
        "dua_infani_bima_allamtani" to DuaText("당신이 나에게 가르쳐준 것으로 나에게 유익을 주세요", "오 알라, 당신이 나에게 가르쳐준 것으로 나에게 유익을 주고, 나에게 유익이 될 것이 무엇인지 가르쳐 주고, 지식을 늘려 주십시오.", "지식을 구하는 동안이나 공부하기 전에.", "유익한 지식과 그에 따른 행동에 대한 이중입니다."),
    )
}
